<form class="filter-row" method="get"><input class="form-control" name="q" placeholder="Mã đơn hàng" aria-label="Mã đơn hàng" value="<?= e($filters['q']??'') ?>"><select class="form-select" name="status" aria-label="Trạng thái"><option value="">Mọi trạng thái</option><?php foreach(array_keys(App\Services\OrderStatusService::TRANSITIONS) as $s):?><option value="<?= $s ?>" <?= ($filters['status']??'')===$s?'selected':'' ?>><?= e(status_label($s)) ?></option><?php endforeach?></select><input class="form-control" type="date" name="start" aria-label="Từ ngày" value="<?= e($filters['start']??'') ?>"><input class="form-control" type="date" name="end" aria-label="Đến ngày" value="<?= e($filters['end']??'') ?>"><button class="btn btn-primary" type="submit">Lọc đơn hàng</button></form><section class="panel table-wrap"><table class="table"><thead><tr><th>Mã đơn / Ngày đặt</th><th>Khách hàng</th><th>Giá trị</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><b><?= e($o['code']) ?></b><small class="d-block muted"><?= e($o['created_at']) ?></small></td><td><?= e($o['customer_name']) ?></td><td><?= money($o['total']) ?></td><td><span class="status <?= e($o['status']) ?>"><?= e(status_label($o['status'])) ?></span></td><td><a href="/admin/orders/<?= $o['id'] ?>" class="btn btn-light btn-sm">Chi tiết ↗</a></td></tr><?php endforeach?></tbody></table></section><?php require __DIR__.'/pagination.php';?>
